// stage.mjs — turns a story module into frames: timing, camera, cached sets, and the measurements
// the quality gates read. You normally do not edit this file; you write `story.mjs`.
//
// A story module default-exports:
//   { title, fps (30 or 60), voice:{name, speed}, music:{bpm}, light:[dx,dy], tint, shots:[ … ] }
// and each shot is:
//   { id, kind:'scene'|'board'|'map'|'insert'|'title', say:'…' | ['clause', 'clause'], pause, hold,
//     light, tint, key,                      // lighting for this shot (overrides the story's)
//     set(c, s),                             // the painted background, drawn once and cached
//     camera(t, s) -> {x, y, zoom, tilt},    // optional; default is a slow push-in
//     draw(c, t, s),                         // everything that acts: figures, props, labels, effects
//     overlay(c, t, s),                      // optional, drawn after the camera (fixed to the screen)
//     wide: true,                            // declares a deliberate wide shot with small figures
//     sfx:[{at, type, gain, pan}] }          // `at` in seconds from the shot start, or 'cue1', 'cue2'…
// `s` is the shot clock: s.dur, s.cue(i) (when clause i starts), s.end(i) (when it stops),
// s.voiceAt(t) (loudness 0..1), s.index, s.id.
import { pathToFileURL } from 'node:url';
import { createCanvas, W, H, S, REG, resetReg, withStyle, rad, clamp, initFont } from './ink.mjs';
import { drift } from './motion.mjs';

export const MARGIN = 200;          // sets are painted this far beyond the frame on every side
export const SET_SCALE = 1.25;      // and a little oversampled, so snap zooms stay crisp

export async function loadStory(file) {
  const mod = await import(pathToFileURL(file).href + `?v=${Date.now()}`);
  const story = mod.default ?? mod.story;
  if (!story?.shots?.length) throw new Error('The story module must default-export an object with a non-empty `shots` array.');
  story.shots.forEach((sh, i) => { sh.id ??= `shot${i + 1}`; sh.kind ??= 'scene'; if (typeof sh.say === 'string') sh.say = [sh.say]; sh.say ??= []; });
  return story;
}
const WORDS = s => (s.match(/[\p{L}\p{N}']+/gu) ?? []).length;
// What film.py needs to know to make the voice track.
export function describe(story) {
  return { title: story.title ?? 'Untitled', fps: story.fps ?? 30, voice: story.voice ?? {}, music: story.music ?? {},
    shots: story.shots.map(sh => ({ id: sh.id, kind: sh.kind, say: sh.say, pause: sh.pause ?? 0.22, gap: sh.gap ?? 0.1, hold: sh.hold ?? 0, lead: sh.lead ?? 0, sfx: sh.sfx ?? [], musicStop: !!sh.musicStop, words: sh.say.reduce((n, q) => n + WORDS(q), 0) })) };
}
// Only fields that affect speech/timing, independent of visual edits and sound cues.
export function speechSpec(story) {
  const d = describe(story);
  return [d.voice, d.shots.map(sh => [sh.id, sh.say, sh.lead, sh.gap, sh.pause, sh.hold])];
}
// A stand-in timeline from word counts, so pictures can be drafted before any voice exists.
export function draftTimeline(story) {
  let t = 0; const shots = [];
  for (const sh of story.shots) {
    let u = sh.lead ?? 0; const cues = [], ends = [];
    for (const q of sh.say) { cues.push(u); u += Math.max(0.5, WORDS(q) / 2.9); ends.push(u); u += sh.gap ?? 0.1; }
    const dur = Math.max(1.2, u + (sh.pause ?? 0.22) + (sh.hold ?? 0)); shots.push({ id: sh.id, start: t, end: t + dur, cues, ends }); t += dur;
  }
  return { draft: true, duration: t, fps: story.fps ?? 30, envRate: 60, envelope: [], shots };
}
export function context(story, tl, i) {
  const m = tl.shots[i], env = tl.envelope ?? [], rate = tl.envRate ?? 60, dur = m.end - m.start;
  const s = { index: i, id: story.shots[i].id, dur, start: m.start, cues: m.cues ?? [0], ends: m.ends ?? [dur], fps: tl.fps ?? 30,
    cue: k => (m.cues ?? [0])[k] ?? dur, end: k => (m.ends ?? [dur])[k] ?? dur,
    voiceAt: t => { if (t < 0 || t > dur) return 0; if (!env.length) { const k = (m.cues ?? []).findLastIndex(q => q <= t); return k >= 0 && t < (m.ends?.[k] ?? dur) ? 0.35 + 0.65 * Math.abs(Math.sin(t * 17) * Math.sin(t * 5.3)) : 0; } return env[Math.min(env.length - 1, Math.floor((m.start + t) * rate))] ?? 0; } };
  return s;
}
function styleOf(story, shot) {
  const L = shot.light ?? story.light ?? [0.62, -0.78], n = Math.hypot(L[0], L[1]) || 1, st = { light: [L[0] / n, L[1] / n] };
  const tint = shot.tint ?? story.tint; if (tint) st.shadowTint = tint;
  const key = shot.key ?? story.key; if (key) st.key = key;
  const form = shot.form ?? story.form; if (form !== undefined) st.form = form;
  const back = shot.backlit ?? story.backlit; st.backlit = back === true ? 0.17 : (back || 0);
  return st;
}
export function cameraOf(shot, t, s) {
  const base = { x: W / 2, y: H / 2, zoom: 1, tilt: 0 };
  const cam = shot.camera ? shot.camera(t, s) : drift(t, s.dur, { zoom: 1.0 }, { zoom: 1.035 });
  return { ...base, ...cam };
}
const setCache = new Map();
function paintSet(story, shot, s) {
  if (!shot.set) return null;
  const key = shot.setKey ?? shot.set, style = styleOf(story, shot), sub = JSON.stringify(style);
  let per = setCache.get(key); if (!per) { per = new Map(); setCache.set(key, per); }
  if (per.has(sub)) return per.get(sub);
  const k = SET_SCALE, cv = createCanvas(Math.round((W + 2 * MARGIN) * k), Math.round((H + 2 * MARGIN) * k)), c = cv.getContext('2d');
  c.setTransform(k, 0, 0, k, MARGIN * k, MARGIN * k);
  resetReg();
  withStyle({ ...style, dpx: k, view: k, mode: 'full' }, () => shot.set(c, s));
  // lettering and figures painted into the set are remembered in scene coordinates, so the gates can
  // measure them through the moving camera on every frame
  const entry = { cv, labels: REG.labels.map(l => ({ ...l, box: l.box.map(v => v - MARGIN) })), faces: REG.faces.map(f => ({ ...f, x: f.x - MARGIN, y: f.y - MARGIN, extra: true })) };
  per.set(sub, entry); return entry;
}
export function clearSets() { setCache.clear(); layerCache.clear(); }
// painted(c, key, fn): paint a static piece once and reuse it on every frame. Call it from `draw`, in
// whatever order you need, for scenery that must sit IN FRONT of the cast: a wall they stand behind, a
// desk, a doorway, a cropped foreground figure. fn(c) paints in scene coordinates like a set.
// (Lettering and figures inside a painted piece are not seen by the gates; keep lettering in `draw`.)
const layerCache = new Map();
export function painted(c, key, fn) {
  if (S.mode !== 'full') { fn(c); return; }
  const sub = key + '|' + JSON.stringify([S.light, S.shadowTint, S.key, S.backlit, S.form]);
  let cv = layerCache.get(sub);
  if (!cv) {
    const k = SET_SCALE; cv = createCanvas(Math.round((W + 2 * MARGIN) * k), Math.round((H + 2 * MARGIN) * k));
    const lc = cv.getContext('2d'); lc.setTransform(k, 0, 0, k, MARGIN * k, MARGIN * k);
    const keep = [REG.faces.slice(), REG.labels.slice()];
    withStyle({ dpx: k, view: k, mode: 'full' }, () => fn(lc));
    REG.faces.length = 0; REG.faces.push(...keep[0]); REG.labels.length = 0; REG.labels.push(...keep[1]);
    layerCache.set(sub, cv);
  }
  c.save(); c.imageSmoothingEnabled = true; c.imageSmoothingQuality = 'high'; c.drawImage(cv, -MARGIN, -MARGIN, W + 2 * MARGIN, H + 2 * MARGIN); c.restore();
}
// Draw one frame of shot i at local time t into context c (device scale dp). Returns what was registered.
export function drawFrame(c, story, tl, i, t, dp = 1) {
  const shot = story.shots[i], s = context(story, tl, i), style = styleOf(story, shot);
  initFont();
  const cam = cameraOf(shot, t, s), bg = paintSet(story, shot, s);
  resetReg();
  c.setTransform(dp, 0, 0, dp, 0, 0); c.fillStyle = shot.backdrop ?? '#120a0e'; c.fillRect(0, 0, W, H);
  c.save(); c.translate(W / 2, H / 2); c.rotate(rad(cam.tilt)); c.scale(cam.zoom, cam.zoom); c.translate(-cam.x, -cam.y);
  withStyle({ ...style, dpx: dp, view: dp * cam.zoom, mode: 'full' }, () => {
    if (bg) { c.imageSmoothingEnabled = true; c.imageSmoothingQuality = 'high'; c.drawImage(bg.cv, -MARGIN, -MARGIN, W + 2 * MARGIN, H + 2 * MARGIN); }
    shot.draw?.(c, t, s);
  });
  c.restore();
  if (shot.overlay) withStyle({ ...style, dpx: dp, view: dp, mode: 'full' }, () => shot.overlay(c, t, s));
  if (shot.flash && t < 0.1) { c.fillStyle = `rgba(255,250,235,${clamp(1 - t / 0.1)})`; c.fillRect(0, 0, W, H); }
  const a = rad(cam.tilt), ca = Math.cos(a), sa = Math.sin(a);
  const proj = (x, y) => { const dx = (x - cam.x) * cam.zoom, dy = (y - cam.y) * cam.zoom; return [W / 2 + dx * ca - dy * sa, H / 2 + dx * sa + dy * ca]; };
  const fromSet = bg ? { labels: bg.labels.map(l => { const q = [proj(l.box[0], l.box[1]), proj(l.box[2], l.box[1]), proj(l.box[2], l.box[3]), proj(l.box[0], l.box[3])]; return { ...l, px: l.px * cam.zoom, box: [Math.min(...q.map(v => v[0])), Math.min(...q.map(v => v[1])), Math.max(...q.map(v => v[0])), Math.max(...q.map(v => v[1]))] }; }), faces: bg.faces.map(f => { const q = proj(f.x, f.y); return { ...f, x: q[0], y: q[1], r: f.r * cam.zoom }; }) } : { labels: [], faces: [] };
  return { cam, faces: [...fromSet.faces, ...REG.faces.map(f => ({ ...f }))], labels: [...fromSet.labels, ...REG.labels.map(l => ({ ...l }))] };
}

// ------------------------------------------------------------------ measurements for the gates
export function imageStats(c, w, h) {
  const d = c.getImageData(0, 0, w, h).data; let sat = 0, n = 0, ink = 0, sum = 0, sum2 = 0, white = 0;
  for (let i = 0; i < d.length; i += 4) {
    const r = d[i], g = d[i + 1], b = d[i + 2], mx = Math.max(r, g, b), mn = Math.min(r, g, b), l = 0.299 * r + 0.587 * g + 0.114 * b;
    if (l < 46) ink++; if (mn > 238) white++; sum += l; sum2 += l * l;
    if (mx > 60) { sat += (mx - mn) / mx; n++; }
  }
  const px = d.length / 4, mean = sum / px;
  return { saturation: +(sat / Math.max(1, n)).toFixed(3), ink: +(ink / px).toFixed(3), white: +(white / px).toFixed(3), contrast: +Math.sqrt(Math.max(0, sum2 / px - mean * mean)).toFixed(1) };
}
export function frameDiff(a, b) { let s = 0; for (let i = 0; i < a.length; i += 4) s += Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2]); return s / (a.length / 4 * 3); }
const CLASS = r => r >= 200 ? 'close' : r >= 110 ? 'medium' : r >= 55 ? 'full' : 'tiny';

// Per-shot and whole-film checks on what was drawn. `shots` = [{id, kind, wide, dur, samples:[{t, faces, labels}], motion:[…], stats, setKey}].
export function audit(story, shots) {
  const film = [];
  for (const sh of shots) {
    const issues = sh.issues = [], all = sh.samples.flatMap(q => q.faces.filter(f => !f.extra)), big = all.reduce((m, f) => Math.max(m, f.r), 0);
    sh.headPx = Math.round(big * 2); sh.framing = big ? CLASS(big) : 'none';
    if (sh.kind === 'scene') {
      if (!all.length) issues.push('No character on screen. A scene shot needs an acting figure; if this is an object or document close-up set kind:"insert".');
      else if (sh.framing === 'tiny' && !sh.wide) issues.push(`Characters are tiny (largest head ${sh.headPx}px of 960). Move the camera in or enlarge the figures; set wide:true only for a deliberate establishing shot.`);
      else if (sh.framing === 'full' && !sh.wide && big < 70) issues.push(`Largest head is only ${sh.headPx}px tall. Full-figure shots need heads of at least 140px; declare wide:true if the smallness is the point.`);
      // the subject of a frame is the largest face whose centre is on screen; its eyes and mouth must be inside
      const cut = new Set();
      for (const q of sh.samples) {
        const on = q.faces.filter(g => !g.extra && g.x > 0 && g.x < W && g.y > 0 && g.y < H); if (!on.length) continue;
        const f = on.reduce((a, b) => b.r > a.r ? b : a), k = f.r * 0.5;
        if ((f.x - k < 6 || f.x + k > W - 6 || f.y - k < 6 || f.y + k > H - 6) && !cut.has(f.id)) { cut.add(f.id); issues.push(`${f.id}: the main face is cut by the frame at ${q.t.toFixed(1)}s. Crop the skull, hat or chin if you like, but keep eyes and mouth inside the frame (or move the camera so that this figure is fully out).`); }
      }
    }
    for (const q of sh.samples) for (const l of q.labels) {
      const min = l.scrawl ? 30 : 38;
      if (l.px < min) issues.push(`Text "${l.text.slice(0, 24)}" is ${Math.round(l.px)}px; minimum is ${min}px at delivery size.`);
      if (l.box[0] < 20 || l.box[2] > W - 20 || l.box[1] < 14 || l.box[3] > H - 14) issues.push(`Text "${l.text.slice(0, 24)}" runs out of the frame at ${q.t.toFixed(1)}s.`);
    }
    // nothing-happens detector: half-second samples whose pictures barely differ
    let run = 0, worst = 0; for (const d of sh.motion) { run = d < 2.0 ? run + 1 : 0; worst = Math.max(worst, run); }
    sh.longestStill = worst * 0.5;
    if (sh.longestStill > 4.5) issues.push(`Nothing changes for ${sh.longestStill.toFixed(1)}s. Give the shot a pose swap, a prop action, a pop-in or a snap zoom on a word; a held drawing with a moving mouth lasts about 4 seconds at most.`);
    if (sh.dur > 10) issues.push(`Shot runs ${sh.dur.toFixed(1)}s. Split the narration into two shots with different framing.`);
    if (sh.stats) {
      if (sh.stats.contrast < 34) issues.push(`Flat picture (contrast ${sh.stats.contrast}). Add a dark foreground, a cast shadow or a brighter light source.`);
      if (sh.kind === 'scene' && sh.stats.saturation < 0.2) issues.push(`Washed-out colour (saturation ${sh.stats.saturation}). Use saturated local colours; this style is never sepia or pastel.`);
      if (sh.stats.ink < 0.012) issues.push('Almost no ink line in the picture. Outline the forms.');
    }
    issues.splice(0, issues.length, ...new Set(issues));
  }
  const scenes = shots.filter(q => q.kind === 'scene');
  if (scenes.length >= 3) {
    const closeShare = scenes.filter(q => q.framing === 'close').length / scenes.length;
    if (closeShare < 0.3) film.push(`Only ${Math.round(closeShare * 100)}% of scene shots are close-ups (head taller than 400px). This format lives on big cropped heads: aim for a third or more.`);
    if (new Set(scenes.map(q => q.framing)).size < 2) film.push('Every scene shot uses the same framing. Mix close-ups, medium two-shots and at least one full-figure or wide shot.');
    for (let i = 2; i < shots.length; i++) { const a = shots[i - 2], b = shots[i - 1], d = shots[i]; if (a.kind === 'scene' && b.kind === 'scene' && d.kind === 'scene' && a.setKey === b.setKey && b.setKey === d.setKey && a.framing === b.framing && b.framing === d.framing) film.push(`Shots ${a.id}, ${b.id}, ${d.id}: three in a row on the same set with the same framing. Change the angle, the distance or the place.`); }
    const sigs = []; for (const sh of scenes) { const mid = sh.samples[Math.floor(sh.samples.length / 2)]; for (const f of mid.faces.filter(g => !g.extra)) sigs.push([sh.id, f.id, f.sig]); }
    const distinct = new Set(sigs.map(q => q[2])).size;
    if (sigs.length >= 4 && distinct / sigs.length < 0.6) film.push(`Faces repeat: ${distinct} different expressions across ${sigs.length} appearances. Draw a new expression (eyes, brows, mouth, head tilt) for nearly every shot.`);
    for (let i = 1; i < scenes.length; i++) for (const f of sigs.filter(q => q[0] === scenes[i].id)) if (sigs.some(q => q[0] === scenes[i - 1].id && q[1] === f[1] && q[2] === f[2])) film.push(`${f[1]} has the same face and pose in ${scenes[i - 1].id} and ${scenes[i].id}.`);
  }
  const sets = new Set(shots.map(q => q.setKey)).size;
  if (shots.length >= 6 && sets < Math.ceil(shots.length / 3)) film.push(`Only ${sets} different sets for ${shots.length} shots. Paint a new place, time of day or angle at least every third shot.`);
  const total = shots.reduce((n, q) => n + q.dur, 0);
  if (total >= 40 && !shots.some(q => q.kind === 'board' || q.kind === 'map' || q.kind === 'insert')) film.push('No explanation insert. Films of this format cut to a blueprint board, a map or a document close-up at least once.');
  return { film: [...new Set(film)], shots };
}
